"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[88546],{14544:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"XPController","desc":"Bridges XP replication into the client. On `XPStateSync` it re-fires\\n`Signals.OnXPChanged` (reserved for a future XP HUD bar). `XPLevelUp` is\\nbroadcast: every client plays the `XPConfig.LEVELUP_VFX` burst at the feet\\nof the player who leveled up, and that player\'s own client also raises the\\nlevel-up toast via `Signals.RequestNotification`. Runs in both the lobby and\\ngameplay places (no template in ReplicatedStorage \u2192 no VFX).","realm":["Client"],"source":{"line":13,"path":"src/StarterPlayer/StarterPlayerScripts/XPController.client.luau"}}')}}]);